  const off = distance % 1.4;
  for (let z = 1.4 - off; z < 24; z += 1.4) {
    const a = proj(-1.6, 0, z), b = proj(1.6, 0, z);
    ctx.lineWidth = Math.max(1, 6 * a.scale);
    ctx.beginPath(); ctx.moveTo(a.sx, a.sy); ctx.lineTo(b.sx, b.sy); ctx.stroke();
  }

  // rails per lane (gold glints)
  ctx.strokeStyle = "rgba(255,215,0,0.18)";
  ctx.lineWidth = Math.max(1, W * 0.002);
  for (let l = 0; l < 3; l++) {
    for (const dx of [-0.28, 0.28]) {
      const a = proj(laneX(l) + dx, 0, -0.6), b = proj(laneX(l) + dx, 0, 26);
      ctx.beginPath(); ctx.moveTo(a.sx, a.sy); ctx.lineTo(b.sx, b.sy); ctx.stroke();
    }
  }
}

function drawObstacle(o) {
  const x = laneX(o.lane);
  if (o.type === "train") {
    const zFar = Math.min(o.z + o.len, 25);
    const zNear = Math.max(o.z, -0.8);
    if (zFar <= zNear) return;
    const front = worldRect(x, 0, zNear, 0.92, o.h);
    const back = worldRect(x, 0, zFar, 0.92, o.h);
    // body side polygon
    ctx.fillStyle = "#2a2a44";
    ctx.beginPath();
    ctx.moveTo(front.x, front.y); ctx.lineTo(front.x + front.w, front.y);
    ctx.lineTo(back.x + back.w, back.y); ctx.lineTo(back.x, back.y);
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = "#20203a";
    ctx.beginPath();
    ctx.moveTo(front.x, front.y + front.h); ctx.lineTo(front.x + front.w, front.y + front.h);
    ctx.lineTo(back.x + back.w, back.y + back.h); ctx.lineTo(back.x, back.y + back.h);
    ctx.closePath(); ctx.fill();
    // front face with objects sprite
    if (!IMG.objects || !imgOk(IMG.objects) ||
        !drawTrainFace(front)) {
      ctx.fillStyle = C.red;
      ctx.fillRect(front.x, front.y, front.w, front.h);
      ctx.fillStyle = C.gold;
      ctx.fillRect(front.x + front.w * 0.1, front.y + front.h * 0.15, front.w * 0.35, front.h * 0.25);
      ctx.fillRect(front.x + front.w * 0.55, front.y + front.h * 0.15, front.w * 0.35, front.h * 0.25);
    }
    ctx.strokeStyle = C.cyan;
    ctx.lineWidth = Math.max(1, 2 * front.scale * 3);
    ctx.strokeRect(front.x, front.y, front.w, front.h);
  } else if (o.type === "barrier") {
    const r = worldRect(x, 0, o.z, 0.9, 0.5);
    if (!drawObjSprite(r, 0)) {
      ctx.fillStyle = C.orange;
      ctx.fillRect(r.x, r.y, r.w, r.h);
      ctx.fillStyle = "#fff";
      for (let i = 0; i < 4; i++) {
        ctx.fillRect(r.x + (i * 2) * r.w / 8, r.y + r.h * 0.3, r.w / 8, r.h * 0.4);
      }
    }
    ctx.strokeStyle = C.gold;
    ctx.lineWidth = Math.max(1, 3 * r.scale);
    ctx.strokeRect(r.x, r.y, r.w, r.h);
  } else {
    // sign: overhead panel with legs, gap underneath to roll through
    const legs = worldRect(x, 0, o.z, 0.95, 2.6);
    const panel = worldRect(x, 0.75, o.z, 0.95, 1.85);
    ctx.fillStyle = "#333355";
    const lw = Math.max(2, legs.w * 0.08);
    ctx.fillRect(legs.x, legs.y, lw, legs.h);
    ctx.fillRect(legs.x + legs.w - lw, legs.y, lw, legs.h);
    if (!drawObjSprite(panel, 1)) {
      ctx.fillStyle = C.pink;
      ctx.fillRect(panel.x, panel.y, panel.w, panel.h);
      ctx.fillStyle = "#fff";
      ctx.font = `bold ${Math.max(8, panel.h * 0.4)}px sans-serif`;
      ctx.textAlign = "center"; ctx.textBaseline = "middle";
      ctx.fillText("!", panel.x + panel.w / 2, panel.y + panel.h / 2);
    }
    ctx.strokeStyle = C.pink;
    ctx.lineWidth = Math.max(1, 3 * panel.scale);
    ctx.strokeRect(panel.x, panel.y, panel.w, panel.h);
  }
}

function drawTrainFace(r) {
  const im = IMG.objects;
  if (!imgOk(im)) return false;
  const sw = im.naturalWidth / 2, sh = im.naturalHeight;
  ctx.drawImage(im, 0, 0, sw, sh, r.x, r.y, r.w, r.h);
  return true;
}

function drawObjSprite(r, half) {
  const im = IMG.objects;
  if (!imgOk(im)) return false;
  const sw = im.naturalWidth / 2, sh = im.naturalHeight;
  ctx.drawImage(im, half * sw, 0, sw, sh, r.x, r.y, r.w, r.h);
  return true;
}

function drawCoin(c) {
  const p = proj(c.x, c.y, c.z);
  const rad = Math.max(2, roadScale * 0.045 * p.scale);
  const wob = Math.sin(tNow * 6 + c.z * 3) * 0.25 + 0.75;
  ctx.save();
  ctx.translate(p.sx, p.sy);
  ctx.scale(wob, 1);
  ctx.fillStyle = C.gold;
  ctx.beginPath(); ctx.arc(0, 0, rad, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = "#b8860b";
  ctx.beginPath(); ctx.arc(0, 0, rad * 0.55, 0, Math.PI * 2); ctx.fill();
  ctx.restore();
}

function drawPowerup(p) {
  const pr = proj(p.x, p.y + Math.sin(p.spin) * 0.1, p.z);
  const rad = Math.max(4, roadScale * 0.07 * pr.scale);
  const col = p.kind === "magnet" ? C.cyan : p.kind === "jetpack" ? C.orange : C.pink;
  ctx.save();
  ctx.translate(pr.sx, pr.sy);
  ctx.shadowColor = col; ctx.shadowBlur = rad;
  ctx.fillStyle = col;
  ctx.beginPath(); ctx.arc(0, 0, rad, 0, Math.PI * 2); ctx.fill();
  ctx.shadowBlur = 0;
  ctx.fillStyle = "#000";
  ctx.font = `bold ${Math.max(6, rad * 1.1)}px sans-serif`;
  ctx.textAlign = "center"; ctx.textBaseline = "middle";
  ctx.fillText(p.kind === "magnet" ? "M" : p.kind === "jetpack" ? "J" : "x2", 0, 1);
  ctx.restore();
}

function drawPlayer() {
  const ph = player.rolling ? 0.6 : 1.2;
  const r = worldRect(player.x, player.y, 0, 0.62, ph);
  // shadow
  const sh = worldRect(player.x, 0, 0, 0.6, 0.06);
  ctx.fillStyle = "rgba(0,0,0,0.45)";
  ctx.beginPath();
  ctx.ellipse(sh.x + sh.w / 2, sh.y + sh.h / 2, sh.w / 2, Math.max(2, sh.w * 0.14), 0, 0, Math.PI * 2);
  ctx.fill();
  // jetpack flame
  if (jetTimer > 0) {
    ctx.fillStyle = C.orange;
    ctx.beginPath();
    ctx.moveTo(r.x + r.w * 0.3, r.y + r.h);
    ctx.lineTo(r.x + r.w * 0.7, r.y + r.h);
    ctx.lineTo(r.x + r.w * 0.5, r.y + r.h + r.h * (0.3 + Math.random() * 0.25));
    ctx.closePath(); ctx.fill();
  }
  const bob = player.y <= 0.01 && !player.rolling ? Math.abs(Math.sin(player.runT * 2)) * r.h * 0.05 : 0;
  ctx.save();
  if (player.rolling) {
    ctx.translate(r.x + r.w / 2, r.y + r.h / 2);
    ctx.rotate(Math.sin(tNow * 20) * 0.08);
    ctx.translate(-(r.x + r.w / 2), -(r.y + r.h / 2));
  }
  const im = IMG.player;
  if (imgOk(im)) {
    ctx.drawImage(im, r.x - r.w * 0.25, r.y - bob, r.w * 1.5, r.h);
  } else {
    ctx.fillStyle = C.cyan;
    ctx.fillRect(r.x, r.y - bob, r.w, r.h);
    ctx.fillStyle = C.gold;
    ctx.beginPath();
    ctx.arc(r.x + r.w / 2, r.y - bob + r.h * 0.15, r.w * 0.3, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
  // magnet aura
  if (magnetTimer > 0) {
    ctx.strokeStyle = "rgba(0,229,255,0.5)";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(r.x + r.w / 2, r.y + r.h / 2, r.w * (1.1 + Math.sin(tNow * 5) * 0.15), 0, Math.PI * 2);
    ctx.stroke();
  }
}

function drawParticles() {
  for (const pa of particles) {
    const p = proj(pa.x, Math.max(0, pa.y), pa.z);
    const rad = Math.max(1, roadScale * 0.02 * p.scale * (pa.life * 2));
    ctx.globalAlpha = Math.max(0, Math.min(1, pa.life * 2.2));
    ctx.fillStyle = pa.col;
    ctx.beginPath(); ctx.arc(p.sx, p.sy, rad, 0, Math.PI * 2); ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function fs(px) { return Math.max(11, Math.round(px)); }

function drawHUD() {
  const pad = Math.max(10, W * 0.03);
  ctx.textAlign = "left"; ctx.textBaseline = "top";
  ctx.font = `bold ${fs(W * 0.055)}px sans-serif`;
  ctx.fillStyle = C.cyan;
  ctx.fillText("SCORE " + Math.floor(score), pad, pad);
  ctx.font = `bold ${fs(W * 0.042)}px sans-serif`;
  ctx.fillStyle = C.gold;
  ctx.fillText("● " + coinCount, pad, pad + fs(W * 0.055) + 6);
  ctx.fillStyle = "rgba(255,255,255,0.6)";
  ctx.font = `${fs(W * 0.034)}px sans-serif`;
  ctx.fillText("HI " + Math.max(highScore, Math.floor(score)), pad, pad + fs(W * 0.055) + fs(W * 0.042) + 14);

  // power-up timers
  let py = pad + fs(W * 0.055) + fs(W * 0.042) + fs(W * 0.034) + 24;
  const bw = W * 0.28, bh = Math.max(5, H * 0.008);
  const bars = [
    [magnetTimer, T.magnetDuration, C.cyan, "MAGNET"],
    [jetTimer, T.jetpackDuration, C.orange, "JETPACK"],
    [multTimer, T.multiplierDuration, C.pink, "x2 SCORE"]
  ];
  ctx.font = `bold ${fs(W * 0.026)}px sans-serif`;
  for (const [t, max, col, label] of bars) {
    if (t <= 0) continue;
    ctx.fillStyle = "rgba(255,255,255,0.15)";
    ctx.fillRect(pad, py, bw, bh);
    ctx.fillStyle = col;
    ctx.fillRect(pad, py, bw * Math.max(0, t / max), bh);
    ctx.fillText(label, pad + bw + 8, py - fs(W * 0.026) * 0.3);
    py += bh + 10;
  }

  // pause button
  const pb = pauseBtnRect();
  ctx.fillStyle = "rgba(255,255,255,0.12)";
  roundRect(pb.x, pb.y, pb.w, pb.h, 8); ctx.fill();
  ctx.fillStyle = "#fff";
  if (state === S.PAUSE) {
    ctx.beginPath();
    ctx.moveTo(pb.x + pb.w * 0.35, pb.y + pb.h * 0.28);
    ctx.lineTo(pb.x + pb.w * 0.35, pb.y + pb.h * 0.72);
    ctx.lineTo(pb.x + pb.w * 0.72, pb.y + pb.h * 0.5);
    ctx.closePath(); ctx.fill();
  } else {
    ctx.fillRect(pb.x + pb.w * 0.3, pb.y + pb.h * 0.28, pb.w * 0.14, pb.h * 0.44);
    ctx.fillRect(pb.x + pb.w * 0.56, pb.y + pb.h * 0.28, pb.w * 0.14, pb.h * 0.44);
  }
}

function roundRect(x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

function drawOverlay(title, sub, lines, titleCol) {
  ctx.fillStyle = "rgba(11,12,16,0.78)";
  ctx.fillRect(0, 0, W, H);
  ctx.textAlign = "center"; ctx.textBaseline = "middle";
  ctx.fillStyle = titleCol;
  ctx.font = `bold ${fs(W * 0.11)}px sans-serif`;
  ctx.fillText(title, W / 2, H * 0.24);
  ctx.fillStyle = "#fff";
  ctx.font = `${fs(W * 0.045)}px sans-serif`;
  let y = H * 0.34;
  for (const ln of lines) {
    ctx.fillText(ln, W / 2, y);
    y += fs(W * 0.045) * 1.7;
  }
  ctx.fillStyle = C.green;
  ctx.font = `bold ${fs(W * 0.05)}px sans-serif`;
  ctx.fillText(sub, W / 2, H * 0.78 + Math.sin(tNow * 4) * 4);
}

function drawPauseMenu() {
  ctx.fillStyle = "rgba(11,12,16,0.7)";
  ctx.fillRect(0, 0, W, H);
  ctx.textAlign = "center"; ctx.textBaseline = "middle";
  ctx.fillStyle = C.cyan;
  ctx.font = `bold ${fs(W * 0.1)}px sans-serif`;
  ctx.fillText("PAUSED", W / 2, H * 0.3);
  const rb = pauseButtons();
  const btn = (r, label, col) => {
    ctx.fillStyle = col;
    roundRect(r.x, r.y, r.w, r.h, 12); ctx.fill();
    ctx.fillStyle = "#000";
    ctx.font = `bold ${fs(r.h * 0.42)}px sans-serif`;
    ctx.fillText(label, r.x + r.w / 2, r.y + r.h / 2);
  };
  btn(rb.resume, "RESUME (P)", C.green);
  btn(rb.restart, "RESTART", C.gold);
}

/* ---------- main loop ---------- */
let last = performance.now();
function frame(now) {
  const dt = Math.min(0.05, (now - last) / 1000);
  last = now;
  tNow = now / 1000;
  computeLayout();

  if (state === S.PLAY) update(dt);
  else {
    // let particles settle on menus / game over
    for (let i = particles.length - 1; i >= 0; i--) {
      const pa = particles[i];
      pa.life -= dt; pa.x += pa.vx * dt; pa.y += pa.vy * dt; pa.vy -= 2 * dt;
      if (pa.life <= 0) particles.splice(i, 1);
    }
  }

  ctx.save();
  if (shake > 0) {
    ctx.translate((Math.random() - 0.5) * shake * 14, (Math.random() - 0.5) * shake * 14);
  }

  drawBackground();
  drawTrack();

  // draw far-to-near
  const drawables = [];
  for (const o of obstacles) drawables.push({ z: o.z + (o.type === "train" ? o.len : 0), kind: "o", ref: o });
  for (const c of coins) drawables.push({ z: c.z, kind: "c", ref: c });
  for (const p of powerups) drawables.push({ z: p.z, kind: "p", ref: p });
  drawables.sort((a, b) => b.z - a.z);
  for (const d of drawables) {
    if (d.ref.z > 25) continue;
    if (d.kind === "o") drawObstacle(d.ref);
    else if (d.kind === "c") drawCoin(d.ref);
    else drawPowerup(d.ref);
  }

  if (!(state === S.OVER && performance.now() - overAt > 200)) drawPlayer();
  drawParticles();

  ctx.restore();

  if (flash > 0) {
    ctx.fillStyle = `rgba(255,255,255,${flash * 0.25})`;
    ctx.fillRect(0, 0, W, H);
  }

  if (state === S.PLAY || state === S.PAUSE) drawHUD();

  if (state === S.MENU) {
    drawOverlay("SUBWAY SPRINT", "TAP / SPACE TO RUN", [
      "Swipe or Arrows: switch lane",
      "Swipe up / Space: jump",
      "Swipe down / Down: roll",
      "P or button: pause",
      "High score: " + highScore
    ], C.cyan);
  } else if (state === S.PAUSE) {
    drawPauseMenu();
  } else if (state === S.OVER) {
    drawOverlay("GAME OVER", "TAP / R TO RESTART", [
      "Score: " + gameOverScore,
      "Coins: " + coinCount,
      "Distance: " + Math.floor(distance * 10) + " m",
      "High score: " + highScore
    ], C.red);
    if (state === S.OVER) drawHUDMini();
  }

  // consume runtime restart flag so it never triggers stale restarts
  if (RT && RT.consumeRestart) RT.consumeRestart();

  requestAnimationFrame(frame);
}

function drawHUDMini() {
  ctx.textAlign = "left"; ctx.textBaseline = "top";
  ctx.font = `${fs(W * 0.03)}px sans-serif`;
  ctx.fillStyle = "rgba(255,255,255,0.5)";
  ctx.fillText("Subway Sprint", 12, 12);
}

requestAnimationFrame(frame);
